export function ChatInterface({
  placeholder = "{{placeholder}}",
  assistantName = "{{assistantName}}",
  accent = "{{accent}}",
  showTyping = {{showTyping}},
}) {
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 360, padding: 14, borderRadius: 14, border: "1px solid #24143014", boxSizing: "border-box" }}>
      <header style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", background: accent, flex: "none" }} />
        <span style={{ fontWeight: 600, fontSize: 13 }}>{assistantName}</span>
      </header>
      <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 10 }}>
        <p style={{ margin: 0, alignSelf: "flex-end", padding: "8px 12px", borderRadius: 12, maxWidth: "82%",
          fontSize: 13.5, background: accent, color: "#241430" }}>Can you summarise this document?</p>
        <p style={{ margin: 0, alignSelf: "flex-start", padding: "8px 12px", borderRadius: 12, maxWidth: "82%",
          fontSize: 13.5, background: "#24143010" }}>Here is a three-line summary of the key points.</p>
        {showTyping && (
          <div role="status" aria-live="polite" style={{ display: "flex", alignItems: "center", gap: 6, alignSelf: "flex-start", padding: "8px 12px" }}>
            <span aria-hidden="true" style={{ display: "inline-flex", gap: 3 }}>
              <span className="ci-dot ci-dot--1" style={{ width: 5, height: 5, borderRadius: "50%", background: "#24143066" }} />
              <span className="ci-dot ci-dot--2" style={{ width: 5, height: 5, borderRadius: "50%", background: "#24143066" }} />
              <span className="ci-dot ci-dot--3" style={{ width: 5, height: 5, borderRadius: "50%", background: "#24143066" }} />
            </span>
            <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>{assistantName} is typing</span>
          </div>
        )}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input type="text" placeholder={placeholder} aria-label="Message" style={{ flex: 1, padding: "8px 10px",
          border: "1.5px solid #24143026", borderRadius: 8, font: "inherit", color: "#241430", background: "#fff", boxSizing: "border-box" }} />
        <button type="button" style={{ background: accent, color: "#241430", border: "none", padding: "8px 14px",
          borderRadius: 8, fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Send</button>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .ci-dot--1 { animation: chat-interface-react-bounce 1s ease-in-out infinite; }
          .ci-dot--2 { animation: chat-interface-react-bounce 1s ease-in-out .15s infinite; }
          .ci-dot--3 { animation: chat-interface-react-bounce 1s ease-in-out .3s infinite; }
          @keyframes chat-interface-react-bounce { 0%, 60%, 100% { transform: translateY(0); opacity: .5; } 30% { transform: translateY(-3px); opacity: 1; } }
        }
      `}</style>
    </section>
  );
}
